const items = $input.all();
const body = items[0].json.body || items[0].json;
const text = body.text || '';

// Parse: question | option1 | option2 | option3
const parts = text.split('|').map(p => p.trim());
const question = parts[0] || 'How are you feeling today?';
const options = parts.slice(1);
if (options.length === 0) {
  options.push('Great', 'Good', 'Okay', 'Not great');
}

const surveyId = `survey-${Date.now()}`;
const channelId = body.channel_id || '';

let surveyMsg = `:bar_chart: *Survey: ${question}*\n\nPlease respond with one of the options below:\n\n`;
options.forEach((opt, i) => {
  const emojis = [':one:', ':two:', ':three:', ':four:', ':five:', ':six:', ':seven:', ':eight:', ':nine:'];
  surveyMsg += `${emojis[i] || ':small_blue_diamond:'} ${opt}\n`;
});
surveyMsg += `\n_Survey ID: ${surveyId} | React with the corresponding number emoji to vote_`;

return [{json: {
  surveyId,
  question,
  options,
  surveyMsg,
  channelId,
  createdBy: body.user_id || '',
  createdAt: new Date().toISOString()
}}];

const items = $input.all();
const responses = items.map(i => i.json);

const counts = {};
for (const r of responses) {
  const choice = r.choice || 'Unknown';
  counts[choice] = (counts[choice] || 0) + 1;
}

const total = responses.length;
let results = `:bar_chart: *Survey Results* (${total} responses)\n\n`;
const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
sorted.forEach(([choice, count]) => {
  const pct = Math.round((count / total) * 100);
  const bar = '█'.repeat(Math.round(pct / 5)) + '░'.repeat(20 - Math.round(pct / 5));
  results += `*${choice}:* ${bar} ${pct}% (${count})\n`;
});

return [{json: {results, total, counts}}];
